using Neemle.CSharpComposer.Model;
using Neemle.CSharpComposer.Rendering;

namespace Neemle.CSharpComposer.Tests.Scenarios;

// The symbol model's shape rules, one row per condition: each option that does not belong to a symbol's mode or
// operation, and each instruction payload that does not belong to its kind, is reported by the rule that owns it.
public static class ShapeScenarios
{
    static readonly CsNode V = Cs.Value(1);

    static readonly CsSymbol R = Cs.Symbol("r");

    static readonly CsAttribute Attr = new(Cs.Type("A"));

    // A tree holding the symbol as a statement value; valid trees render.
    static object S(string? name, CsSymbolOptions options) => Check(Cs.Tree(new CsSymbol(name, options)));

    static object I(InstructionKind kind, CsInstructionOptions options) => Check(Cs.Tree(new CsInstruction(kind, options)));

    static object Check(CsTree tree) => tree.Validate() is { Count: > 0 } errors ? errors : "valid";

    // Parenthesized symbols nested `levels` deep.
    static object Deep(int levels)
    {
        CsNode value = Cs.Value(1);
        for (int i = 0; i < levels; i++) value = Cs.Symbol(new() { AsParenthesized = true, Value = value });
        return Check(Cs.Tree(Cs.Symbol("x", new() { AsVar = true, Value = value })));
    }

